        /**
         * Order owner public key
         */
        userPubkey: string;
        /**
         * Associated market identifier
         */
        marketId: string;
        /**
         * Hashed market identifier used for on-chain PDAs
         */
        marketIdHash: string;
        /**
         * Position PDA used for the order
         */
        positionPubkey: string;
        /**
         * True when the order increases exposure
         */
        isBuy: boolean;
        /**
         * True when the order is on the YES side
         */
        isYes: boolean;
        /**
         * Legacy whole-contract quantity. Use contractsMicro or contractsDecimal for the exact fractional quantity.
         */
        contracts: string;
        /**
         * Contracts in micro-contract units (u64 as string, 1000000 = 1 contract)
         */
        contractsMicro?: string;
        /**
         * Contracts as a decimal string
         */
        contractsDecimal?: string;
        /**
         * Position contracts after executing the order (legacy whole-contract quantity)
         */
        newContracts: string;
        /**
         * Position contracts after the order, in micro-contract units
         */
        newContractsMicro?: string;
        /**
         * Position contracts after the order, as a decimal string
         */
        newContractsDecimal?: string;
        /**
         * Max fill price for buys (micro USD)
         */
        maxBuyPriceUsd: string | null;
        /**
         * Min fill price for sells (micro USD)
         */
        minSellPriceUsd: string | null;
        /**
         * Client provided order identifier
         */
        externalOrderId: string | null;
        /**
         * Notional for this order in micro USD
         */
        orderCostUsd: string;
        /**
         * Average position entry price after the order
         */
