export type GetSwapV2OrderData = {
    body?: never;
    path?: never;
    query: {
        /**
         * The mint address of the input token
         */
        inputMint: string;
        /**
         * The mint address of the output token
         */
        outputMint: string;
        /**
         * The amount to swap in the smallest unit of the input token
         */
        amount: string;
        /**
         * - The public key of the wallet that will sign the transaction
         * - If not provided, the response will contain a quote but no transaction
         * - Must be present if you intend to sign and execute the transaction via `/execute`
         *
         */
        taker?: string;
        /**
         * - The public key of the account that will receive the output tokens
         * - Must differ from `taker`
         * - Expects a wallet address, not a token account
         * - For non-SOL output: tokens are sent to the receiver's associated token account (ATA). If the ATA is not initialised, a create ATA instruction is added to the transaction
         * - For SOL output: native SOL is transferred directly to the receiver
         * - Does not support destination wSOL token accounts
         *
         */
        receiver?: string;
        /**
         * - Swap mode. Currently only `ExactIn` is supported.
         *
         */
        swapMode?: 'ExactIn';
        /**
         * - Slippage tolerance in basis points (0-10000)
         * - If not set, Jupiter automatically determines an appropriate slippage
         *
         */
        slippageBps?: number;
        /**
         * - Address of your referral account for the Jupiter referral project
         * - Must be used together with `referralFee`
         * - See the [Referral Program](/tool-kits/referral-program) for setup
         *
         */
        referralAccount?: string;
        /**
         * - Referral fee in basis points (50-255)
         * - Must be used together with `referralAccount`
         *
         */
        referralFee?: number;
        /**
         * - The public key of an account that will cover gas-related fees (signature fees, priority fees, and rent) on behalf of the taker
         * - Has no effect when set equal to `taker`. Must be a different wallet to activate integrator-sponsored gas
         * - Enabling this restricts routing to Metis (JupiterZ is disabled when an integrator payer is set)
         *
         */
        payer?: string;
        /**
         * - Priority fee in lamports
         * - If not set, Jupiter automatically determines an appropriate priority fee
         * - Setting this overrides the automatic optimisation
         *
         */
        priorityFeeLamports?: number;
        /**
         * - Jito MEV tip in lamports for faster block inclusion
         *
         */
        jitoTipLamports?: number;
        /**
         * - Fee cap strategy: `maxCap` treats the fee as a maximum, `exactFee` uses the exact amount
         * - Ignored if neither `priorityFeeLamports` nor `jitoTipLamports` are set
         *
         */
        broadcastFeeType?: 'maxCap' | 'exactFee';
        /**
         * - Comma-separated list of routers to exclude
         * - Available routers: `metis`, `jupiterz`, `dflow`, `okx`
         *
         */
        excludeRouters?: string;
        /**
         * - Comma-separated list of DEXes to exclude from the Metis router
         * - **Important**: This only affects the Metis router, not other routers
         * - For example: `excludeDexes=Raydium,Orca+V2,Meteora+DLMM`
         *
         */
        excludeDexes?: string;
    };
    url: '/swap/v2/order';
};

export type GetSwapV2OrderErrors = {
    /**
     * Bad request
     */
    400: {
        requestId?: string;
        error?: string;
    };
};

export type GetSwapV2OrderError = GetSwapV2OrderErrors[keyof GetSwapV2OrderErrors];

export type GetSwapV2OrderResponses = {
    /**
     * Quote with optional assembled transaction
     */
    200: {
        /**
         * "ultra" or "manual" based on parameters used
         */
        mode?: string;
        inputMint?: string;
        outputMint?: string;
        inAmount?: string;
        outAmount?: string;
        inUsdValue?: number;
        outUsdValue?: number;
        /**
         * Price impact in percentage points (e.g. -0.1 = -0.1%). Divide by 100 to convert to a decimal fraction.
         */
        priceImpact?: number;
        swapUsdValue?: number;
        /**
         * Minimum output amount after slippage
         */
        otherAmountThreshold?: string;
        swapMode?: string;
        slippageBps?: number;
        /**
         * Deprecated: decimal price impact ratio. Use priceImpact divided by 100 instead.
         *
         * @deprecated
         */
        priceImpactPct?: string;
        routePlan?: Array<SwapV2RoutePlanStep>;
        referralAccount?: string;
        feeMint?: string;
        /**
         * Total fee rate charged for the swap in basis points. This includes the Jupiter platform fee plus any additional charges, such as gasless support cost recoup.
         */
        feeBps?: number;
        platformFee?: SwapV2PlatformFee;
        signatureFeeLamports?: number;
        signatureFeePayer?: string | null;
        /**
         * Includes priority fees and tips (Jito, Nozomi)
         */
        prioritizationFeeLamports?: number;
        prioritizationFeePayer?: string | null;
        /**
         * Estimated rent fee
         */
        rentFeeLamports?: number;
        rentFeePayer?: string | null;
        /**
         * Deprecated: use router instead
         *
         * @deprecated
         */
        swapType?: 'aggregator' | 'rfq' | 'aggregator+rfq' | 'dflow' | 'okx';
        /**
         * Which router won the quote
         */
        router?: 'metis' | 'jupiterz' | 'dflow' | 'okx';
        /**
         * - Base64-encoded transaction. Null if taker is not provided.
         * - Empty string if taker is provided but transaction could not be built (check errorCode).
         *
         */
        transaction?: string | null;
        lastValidBlockHeight?: string;
        /**
         * True when signature and priority fees are paid by a wallet other than the taker. Set by three independent paths:
         * - Automatic Jupiter sponsorship: `signatureFeePayer = gasTzr94Pmp4Gf8vknQnqxeYxdgwFjbgdJa4msYRpnB`
         * - JupiterZ market maker: `signatureFeePayer` is the MM address (varies per quote); Jupiter's gas wallet can pay the rent to create the taker's output token account when referral fees are not set
         * - Integrator payer: `signatureFeePayer` is your `payer` parameter
         * For a deterministic opt-out, check `signatureFeePayer == taker` on every response.
         *
         */
        gasless?: boolean;
        /**
         * Unique request ID. Pass this to /execute.
         */
        requestId?: string;
        /**
         * Response time in milliseconds
         */
        totalTime?: number;
        taker?: string | null;
        /**
         * Quote ID for RFQ swaps
         */
        quoteId?: string;
        /**
         * Market maker address for RFQ swaps
         */
        maker?: string;
        /**
         * Quote expiration timestamp for RFQ swaps
         */
        expireAt?: string;
        /**
         * Present when `taker` is defined and `transaction` is the empty string. The router quoted a price but could not build a transaction. Match on `router` + `errorCode` to identify the error.
         *
         * Aggregator routers (router is metis, dflow, okx):
         * - 1: Insufficient funds
         * - 2: Insufficient SOL for gas
         * - 3: Swap below minimum for gasless
         *
         * JupiterZ router (router is jupiterz):
         * - 1: Insufficient balance to fund the swap
         * - 2: Missing associated token account
         * - 3: Quote could not be built into a transaction
         *
         */
        errorCode?: number;
        /**
         * Human-readable error description. Present when `taker` is defined and `transaction` is the empty string.
         * Match on `router` + `errorCode` instead of this string, as the message text may be parameterised.
         *
         */
        errorMessage?: string;
        /**
         * Duplicate of errorMessage for backwards compatibility
         */
        error?: string;
    };
};

export type GetSwapV2OrderResponse = GetSwapV2OrderResponses[keyof GetSwapV2OrderResponses];

